#include <Wire.h>
#include <Adafruit_BMP280.h>
#include <Adafruit_MPU6050.h>

Adafruit_BMP280 bmp;
Adafruit_MPU6050 mpu;
float groundHpa;                  // pressure on the ground at start

void setup() {
  Serial.begin(115200);
  Wire.begin();                   // SDA = GPIO 21, SCL = GPIO 22
  if (!bmp.begin(0x76)) Serial.println("No BMP280, try 0x77");
  if (!mpu.begin()) Serial.println("No MPU6050");
  groundHpa = bmp.readPressure() / 100.0;   // Pa to hPa
}

void loop() {
  sensors_event_t a, g, t;
  mpu.getEvent(&a, &g, &t);
  float accel = sqrt(a.acceleration.x * a.acceleration.x +
                     a.acceleration.y * a.acceleration.y +
                     a.acceleration.z * a.acceleration.z);   // m/s2
  Serial.printf("%.1f C %.1f hPa %.1f m %.2f m/s2\n", bmp.readTemperature(),
                bmp.readPressure() / 100.0, bmp.readAltitude(groundHpa), accel);
  delay(500);
}

#include <WiFi.h>
#include <esp_now.h>
// ... plus the sensor includes and objects from the last step

struct Packet { uint32_t ms; float tempC, hPa, altM, accel; };   // 20 bytes
uint8_t everyone[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};      // broadcast

void setup() {
  // sensor setup from the last step, then the radio:
  WiFi.mode(WIFI_STA);
  esp_now_init();
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, everyone, 6);
  esp_now_add_peer(&peer);
}

void loop() {
  // read the sensors as before, then fill and send one packet:
  Packet p = {millis(), bmp.readTemperature(), bmp.readPressure() / 100.0,
              bmp.readAltitude(groundHpa), accel};
  esp_now_send(everyone, (uint8_t *)&p, sizeof(p));
  delay(500);
}

#include <WiFi.h>
#include <esp_now.h>

struct Packet { uint32_t ms; float tempC, hPa, altM, accel; };  // same as the sender

// Needs Arduino-ESP32 core 3.0 or newer, which has this callback shape
void onReceive(const esp_now_recv_info_t *info, const uint8_t *data, int len) {
  if (len != sizeof(Packet)) return;            // ignore anything else
  Packet p;
  memcpy(&p, data, sizeof(p));
  Serial.printf("%lu,%.1f,%.1f,%.1f,%.2f\n", (unsigned long)p.ms, p.tempC,
                p.hPa, p.altM, p.accel);        // one CSV line per packet
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  esp_now_init();
  esp_now_register_recv_cb(onReceive);
}

void loop() {}                                  // everything happens in the callback
